document.addEventListener('DOMContentLoaded',function (){const forms=document.querySelectorAll('form');forms.forEach(form=>{form.addEventListener('submit',function (e){const editors=form.querySelectorAll('.pro-editor-mount');editors.forEach((editorMount,index)=>{const hiddenTextarea=editorMount.querySelector('textarea[style*="display:none"]');if (hiddenTextarea){const editorArea=editorMount.querySelector('.pro-editor-content');if (editorArea){const content=editorArea.innerHTML;hiddenTextarea.value=content;const fieldName=hiddenTextarea.getAttribute('data-name')||editorMount.getAttribute('data-field-name');if (!hiddenTextarea.name){hiddenTextarea.name=fieldName;}}else{console.warn(`[Form Sync] No editor area found for editor ${index}`);}}else{console.warn(`[Form Sync] No hidden textarea found for editor ${index}`);}});});});document.addEventListener('blur',function (e){if (e.target&&e.target.classList&&e.target.classList.contains('pro-editor-content')){const editorMount=e.target.closest('.pro-editor-mount');if (editorMount){const hiddenTextarea=editorMount.querySelector('textarea[style*="display:none"]');if (hiddenTextarea){hiddenTextarea.value=e.target.innerHTML;}}}},true);setInterval(function (){const editors=document.querySelectorAll('.pro-editor-mount');editors.forEach(editorMount=>{const hiddenTextarea=editorMount.querySelector('textarea[style*="display:none"]');const editorArea=editorMount.querySelector('.pro-editor-content');if (hiddenTextarea&&editorArea){hiddenTextarea.value=editorArea.innerHTML;}});},5000);});